    _seen_subjects=set()
    for _item in inventory:
        if _item['subject'] not in _seen_subjects:
            _seen_subjects.add(_item['subject'])
            live_rows.append({'subject':_item['subject']})
    visible_keys={x.casefold() for x in visible}
    for row in live_rows:
        # Current-study pages show only the learner's own programme.  Future
        # routes and other markets belong in Pathway Explorer.
        if matric_student and row['subject'].casefold() not in visible_keys:
            continue
        if row['subject'].casefold() not in visible_keys:
            visible.append(row['subject']); visible_keys.add(row['subject'].casefold())
    evidence=learner_answer_evidence(c,student_id)
    # SCOREMAX_STUDENT_EVIDENCE_INDEX_20261114: index the existing evidence
    # once, avoiding one full-array scan for every subject and chapter card.
    by_subject={}
    by_chapter={}
    for row in evidence:
        key=row['subject'].casefold()
        by_subject.setdefault(key,[]).append(row)
        by_chapter.setdefault((key,row['chapter']),[]).append(row)
    # SCOREMAX_NAV_GROUPED_INVENTORY_20261114: one identical governed
    # publication predicate for every visible subject in the programme.
    # Preserve SQLite lower() subject grouping and case-sensitive chapter keys.
    scoped_counts={}
    _chapter_first={}
    for row in inventory:
        key=row['subject_key']
        scoped_counts[key]=scoped_counts.get(key,0)+int(row['question_count'] or 0)
        if row['chapter']:
            pair=(key,row['chapter'])
            old=_chapter_first.get(pair)
            if old is None or row['first_id']<old['first_id']:
                _chapter_first[pair]={'chapter':row['chapter'],'first_id':row['first_id']}
    scoped_chapters={}
    for (key,_chapter),item in _chapter_first.items():
        scoped_chapters.setdefault(key,[]).append(item)
    for chapters in scoped_chapters.values():
        chapters.sort(key=lambda item:item['first_id'])
    # Use the database's own lower(), not Python Unicode lower/casefold.
    # This matches the original native WHERE lower(q.subject)=lower(?).
    _sqlite_subject_keys={}
    def _sqlite_subject_key(label):
        if label not in _sqlite_subject_keys:
            _sqlite_subject_keys[label]=c.execute('SELECT lower(?)',(label,)).fetchone()[0]
        return _sqlite_subject_keys[label]
    data=[]
    _current_menu_coverage=None
    for subject in visible:
        subject_scope=f"lower(q.subject)=lower(?) AND {scope_clause}"
        params=[subject]+scope_params
        qcount=scoped_counts.get(_sqlite_subject_key(subject),0)
        canonical=display_inventory(c,f"SELECT q.subject FROM questions q WHERE {subject_scope} AND {live_question_clause('q')} LIMIT 1",params,columns=('subject',))
        canonical=canonical[0] if canonical else None
        if _menu_projection and canonical is None and subject.casefold() not in _declared_menu_subject_keys:
            continue  # Preserve the native caller's existing coming-soon fallback.
        display=canonical['subject'] if canonical else subject
        if _menu_projection:qcount=int(canonical is not None)
        stats=evidence_summary(by_subject.get(display.casefold(),[]))
        answered=stats['answered'];accuracy=stats['accuracy']
        chapters=[]
        chapter_rows=[] if _summary_only else scoped_chapters.get(_sqlite_subject_key(display),[])
        _label_rows={}
        _keys=list(dict.fromkeys(str(ch['chapter'] or '').strip() for ch in chapter_rows))
        for _offset in range(0,len(_keys),100):
            _batch=_keys[_offset:_offset+100];_marks=','.join('?' for _ in _batch)
            for _row in c.execute("SELECT * FROM chapter_catalogue WHERE active=1 AND lower(subject)=lower(?) AND source_chapter IN ("+_marks+")",[str(display).strip()]+_batch).fetchall():
                _label_rows.setdefault(_row['source_chapter'],[]).append(_row)
        _ph_labels={}
        _ph_size=0
        if canonical_programme(programme)!='MDCAT':
            for _offset in range(0,len(_keys),100):
                _batch=_keys[_offset:_offset+100];_marks=','.join('?' for _ in _batch)
                _cursor=c.execute("""SELECT r.chapter_id,r.programme_id,v.curriculum_json FROM integration_ph_content_releases r
                    JOIN integration_ph_release_question_membership m ON m.release_id=r.release_id AND m.release_version=r.release_version
                    JOIN integration_ph_question_version_store v ON v.question_id=m.question_id AND v.question_version_id=m.question_version_id
                    WHERE r.chapter_id IN ("""+_marks+""") AND lower(replace(r.subject_id,'_',' '))=lower(?) AND r.local_status='ACTIVE'
                    AND EXISTS(SELECT 1 FROM integration_ph_product_activation_authorizations a WHERE a.release_id=r.release_id AND a.release_version=r.release_version
                        AND a.package_checksum_sha256=r.package_checksum_sha256 AND a.activation_status IN ('AUTHORIZED','ACTIVATED'))
                    ORDER BY r.id,m.ordinal LIMIT 5001""",_batch+[str(display)])
                try:
                    for _count,_row in enumerate(_cursor):
                        _ph_size+=len(_row['curriculum_json'] or '')
                        if _count>=5000 or _ph_size>16*1024*1024:
                            _ph_labels=None;break
                        _ph_labels.setdefault(_row['chapter_id'],[]).append(_row)
                finally:_cursor.close()
                if _ph_labels is None:break  # Never use a partial display proof.
        for ch in chapter_rows:
            stats=evidence_summary(by_chapter.get((display.casefold(),ch['chapter']),[]))
            ca=stats['answered'];cp=stats['accuracy']
            identity=chapter_identity(c,programme,display,ch['chapter'],_display_bundle=_label_rows,_ph_display_bundle=_ph_labels)
            chapters.append({**identity,'answered':ca,'accuracy':cp,'status':health_status(cp,ca)})
        if qcount and _current_menu_coverage is None:
            _current_menu_coverage=commercial_access.effective_coverage(c,student_id,programme,
                commercial_gates_enabled=COMMERCIAL_GATES_ENABLED)
        access_state=commercial_access.subject_state(c,student_id,programme,display,
          available=bool(qcount),commercial_gates_enabled=COMMERCIAL_GATES_ENABLED,_coverage=_current_menu_coverage)
        availability='LIVE' if access_state=='INCLUDED' else access_state
        status=health_status(accuracy,answered) if access_state=='INCLUDED' else ('Locked' if access_state=='LOCKED' else 'Coming Soon')
        data.append({'subject':display,'answered':answered,'accuracy':accuracy,'status':status,'chapters':chapters,
                     'availability':availability,'access_state':access_state,'available_questions':int(qcount or 0)})
    if _cache_on:
        from copy import deepcopy
        _cached=getattr(g,'_scoremax_subject_map_cache',{})
        _cached[_cache_key]=deepcopy(data)
        g._scoremax_subject_map_cache=_cached
    return data

